const webhookData = $('Webhook').first().json;
const d = webhookData.body ? webhookData.body : webhookData;

// Determine scoreClass from survivalScore
const scoreRaw = String(d.survivalScore || '').trim();
let scoreClass = 'critical';
const scoreLower = scoreRaw.toLowerCase();
if (scoreLower === 'healthy') scoreClass = 'healthy';
else if (scoreLower === 'marginal') scoreClass = 'marginal';
else if (scoreLower === 'danger') scoreClass = 'danger';
else if (scoreLower === 'critical') scoreClass = 'critical';
else {
  const num = parseFloat(scoreRaw);
  if (!isNaN(num)) {
    if (num >= 75) scoreClass = 'healthy';
    else if (num >= 50) scoreClass = 'marginal';
    else if (num >= 25) scoreClass = 'danger';
  }
}

const auditHtml = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Inter, Arial, Helvetica, sans-serif; background: #06060b; color: #ffffff; padding: 40px; margin: 0; }
  .header { text-align: center; margin-bottom: 40px; }
  .logo { color: #00FF87; font-size: 32px; font-weight: 900; letter-spacing: -1px; }
  .title { color: #ffffff; font-size: 22px; margin-top: 8px; }
  .subtitle { color: rgba(255,255,255,0.6); font-size: 14px; }
  .section { background: #181828; border-radius: 12px; padding: 24px; margin-bottom: 20px; }
  .section-title { color: #00FF87; font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 16px; }
  .metric-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
  .metric { background: #06060b; border-radius: 8px; padding: 16px; }
  .metric-label { color: rgba(255,255,255,0.5); font-size: 11px; text-transform: uppercase; letter-spacing: 1px; }
  .metric-value { font-size: 28px; font-weight: 700; font-family: monospace; margin-top: 4px; }
  .healthy { color: #00FF87; }
  .marginal { color: #ffa726; }
  .danger { color: #ff3d71; }
  .critical { color: #ff1744; }
  .comparison-table { width: 100%; border-collapse: collapse; }
  .comparison-table th { color: rgba(255,255,255,0.5); font-size: 11px; text-transform: uppercase; padding: 8px 12px; text-align: left; }
  .comparison-table td { padding: 12px; border-top: 1px solid #2a2a3a; font-size: 14px; }
  .comparison-table .with-revryze { color: #00FF87; font-weight: 700; }
  .recovery { background: #0a2a1a; border: 1px solid #00FF87; border-radius: 12px; padding: 24px; margin-bottom: 20px; }
  .recovery-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; text-align: center; }
  .footer { text-align: center; color: rgba(255,255,255,0.4); font-size: 12px; margin-top: 40px; }
</style>
</head>
<body>
<div class="header">
  <div class="logo">Revryze</div>
  <div class="title">Presale Survival Test Results</div>
  <div class="subtitle">Prepared for ${d.name || 'N/A'} &mdash; ${d.brandName || 'N/A'}</div>
</div>
<div class="section">
  <div class="section-title">Survival Score</div>
  <div class="metric-grid">
    <div class="metric">
      <div class="metric-label">Projected Members</div>
      <div class="metric-value ${scoreClass}">${d.projectedMembers || '0'}</div>
    </div>
    <div class="metric">
      <div class="metric-label">Status</div>
      <div class="metric-value ${scoreClass}">${d.survivalScore || 'N/A'}</div>
    </div>
    <div class="metric">
      <div class="metric-label">Opening MRR</div>
      <div class="metric-value ${scoreClass}">$${d.openingMRR || '0'}</div>
    </div>
    <div class="metric">
      <div class="metric-label">OPEX Coverage</div>
      <div class="metric-value ${scoreClass}">${d.opexCoverage || '0'}%</div>
    </div>
  </div>
</div>
<div class="section">
  <div class="section-title">Your Plan vs With Revryze</div>
  <table class="comparison-table">
    <tr>
      <th></th>
      <th>Your Plan</th>
      <th class="with-revryze">With Revryze</th>
    </tr>
    <tr>
      <td>Founding Members</td>
      <td>${d.projectedMembers || '0'}</td>
      <td class="with-revryze">200+</td>
    </tr>
    <tr>
      <td>Opening MRR</td>
      <td>$${d.openingMRR || '0'}</td>
      <td class="with-revryze">$30,000</td>
    </tr>
    <tr>
      <td>MRR vs $30K Threshold</td>
      <td>${d.mrrVsThreshold || 'N/A'}</td>
      <td class="with-revryze">Above</td>
    </tr>
    <tr>
      <td>Cash Position at Open</td>
      <td>${d.cashPosition || 'N/A'}</td>
      <td class="with-revryze">Breakeven+</td>
    </tr>
  </table>
</div>
<div class="recovery">
  <div class="section-title">Revenue Recovery Potential</div>
  <div class="recovery-grid">
    <div>
      <div class="metric-value healthy">+${d.recoveryMembers || '0'}</div>
      <div class="metric-label">Additional Members</div>
    </div>
    <div>
      <div class="metric-value healthy">+$${d.recoveryMRR || '0'}</div>
      <div class="metric-label">Additional MRR</div>
    </div>
    <div>
      <div class="metric-value healthy">$${d.recoveryLTV || '0'}</div>
      <div class="metric-label">Recovered LTV</div>
    </div>
  </div>
</div>
<div class="footer">
  Revryze &middot; presale execution for franchise operators &middot; revryze.com
</div>
</body>
</html>`;

return [{
  json: {
    auditHtml,
    email: d.email,
    name: d.name,
    brandName: d.brandName,
    phone: d.phone,
    linkedin: d.linkedin,
    role: d.role,
    unitCount: d.unitCount,
    survivalScore: d.survivalScore,
    projectedMembers: d.projectedMembers,
    openingMRR: d.openingMRR,
    monthlyOpex: d.monthlyOpex,
    opexCoverage: d.opexCoverage,
    mrrVsThreshold: d.mrrVsThreshold,
    cashPosition: d.cashPosition,
    recoveryMembers: d.recoveryMembers,
    recoveryMRR: d.recoveryMRR,
    recoveryLTV: d.recoveryLTV
  }
}];

const claudeResponse = $input.first().json;
// Support both raw Anthropic API format and n8n AI node format
let rawBrief = '';
if (claudeResponse.output) {
  rawBrief = claudeResponse.output;
} else if (claudeResponse.text) {
  rawBrief = claudeResponse.text;
} else if (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) {
  rawBrief = claudeResponse.content[0].text;
} else if (claudeResponse.message) {
  rawBrief = claudeResponse.message;
} else {
  rawBrief = JSON.stringify(claudeResponse);
}
const salesBrief = (rawBrief || 'Sales brief unavailable.')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const auditHtml = $('Build Audit HTML').first().json.auditHtml;

const briefPage = `\n<div style="page-break-before: always; padding: 40px; background: #06060b; color: #fff; font-family: Inter, Arial, Helvetica, sans-serif;">\n  <div style="color: #00FF87; font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 24px;">Sales Brief &mdash; Internal Use Only</div>\n  <div style="background: #181828; border-radius: 12px; padding: 24px; white-space: pre-wrap; line-height: 1.7; color: rgba(255,255,255,0.85);">${salesBrief}</div>\n</div>`;

const combinedHtml = auditHtml.replace('</body>', briefPage + '\n</body>');

return [{
  json: {
    combinedHtml
  }
}];
